CREATE TABLE Users (
    UserID UNIQUEIDENTIFIER PRIMARY KEY DEFAULT NEWID(),
    UserName NVARCHAR(100)
);

-- Database Schema
CREATE TABLE Customers (
    Email VARCHAR(100) NOT NULL PRIMARY KEY,
    Name NVARCHAR(100)
);

-- Application Code (e.g., C# / Entity Framework)
// Parameter @Email is passed as NVARCHAR (Unicode)
SELECT * FROM Customers WHERE Email = @Email;

CREATE TABLE Orders (
    OrderID BIGINT IDENTITY(1,1),
    TotalAmount FLOAT NOT NULL -- Review this line
);

CREATE TABLE ProductAttributes (
    ProductID INT,
    AttributeName VARCHAR(50),
    AttributeValue VARCHAR(MAX)
);

CREATE TABLE IoTLog (
    LogID BIGINT IDENTITY(1,1),
    DeviceID INT,
    StatusCode INT, -- Values are always between 0 and 100
    LogDate DATETIME2(0)
);

SELECT * 
FROM Orders 
WHERE SalesPersonID NOT IN (
    SELECT EmployeeID FROM Employees WHERE Department = 'Inactive'
);

CREATE TABLE Products (
    ProductID INT PRIMARY KEY,
    ProductCode NVARCHAR(MAX) -- 實際資料長度皆小於 50 字元
);
